# [cfg_attr (not (doctest) , doc = " Coin<IOTA> is the token used to pay for gas in IOTA.")] # [cfg_attr (not (doctest) , doc = " It has 9 decimals, and the smallest unit (10^-9) is called \"nano\".")] # [allow (rustdoc :: all)] pub mod iota { # [allow (non_camel_case_types , unused)] type address = :: moverox :: types :: Address ; # [allow (non_camel_case_types , unused)] type u256 = :: moverox :: types :: U256 ; # [allow (non_camel_case_types , unused)] type vector < T > = :: std :: vec :: Vec < T > ; # [cfg_attr (not (doctest) , doc = " Name of the coin")] # [derive (Default , Clone , Debug , PartialEq , Eq , Hash , :: moverox :: traits :: MoveDatatype , :: moverox :: serde :: Deserialize , :: moverox :: serde :: Serialize ,)] # [move_ (crate = :: moverox :: traits)] # [serde (crate = "::moverox::serde")] # [move_ (address = "0x2")] # [move_ (module = iota)] # [allow (non_snake_case)] pub struct IOTA { # [doc = r" BCS for empty structs actually encodes a single boolean hidden field"] dummy_field : bool } impl IOTA { # [allow (clippy :: just_underscores_and_digits , clippy :: too_many_arguments)] pub const fn new () -> Self { Self { dummy_field : false , } } } # [cfg_attr (not (doctest) , doc = " The IOTA token treasury capability.")] # [cfg_attr (not (doctest) , doc = " Protects the token from unauthorized changes.")] # [derive (Clone , Debug , PartialEq , Eq , Hash , :: moverox :: traits :: MoveDatatype , :: moverox :: serde :: Deserialize , :: moverox :: serde :: Serialize ,)] # [move_ (crate = :: moverox :: traits)] # [serde (crate = "::moverox::serde")] # [move_ (address = "0x2")] # [move_ (module = iota)] # [allow (non_snake_case)] pub struct IotaTreasuryCap { pub inner : super :: coin :: TreasuryCap < IOTA > } impl IotaTreasuryCap { # [allow (clippy :: just_underscores_and_digits , clippy :: too_many_arguments)] pub const fn new (inner : super :: coin :: TreasuryCap < IOTA >) -> Self { Self { inner , } } } }
# [cfg_attr (not (doctest) , doc = " Similar to `iota::dynamic_field`, this module allows for the access of dynamic fields. But")] # [cfg_attr (not (doctest) , doc = " unlike, `iota::dynamic_field` the values bound to these dynamic fields _must_ be objects")] # [cfg_attr (not (doctest) , doc = " themselves. This allows for the objects to still exist within in storage, which may be important")] # [cfg_attr (not (doctest) , doc = " for external tools. The difference is otherwise not observable from within Move.")] # [allow (rustdoc :: all)] pub mod dynamic_object_field { # [allow (non_camel_case_types , unused)] type address = :: moverox :: types :: Address ; # [allow (non_camel_case_types , unused)] type u256 = :: moverox :: types :: U256 ; # [allow (non_camel_case_types , unused)] type vector < T > = :: std :: vec :: Vec < T > ; # [derive (Clone , Debug , PartialEq , Eq , Hash , :: moverox :: traits :: MoveDatatype , :: moverox :: serde :: Deserialize , :: moverox :: serde :: Serialize ,)] # [move_ (crate = :: moverox :: traits)] # [serde (crate = "::moverox::serde")] # [move_ (address = "0x2")] # [move_ (module = dynamic_object_field)] # [allow (non_snake_case)] pub struct Wrapper < Name > { pub name : Name } impl < Name > Wrapper < Name > { # [allow (clippy :: just_underscores_and_digits , clippy :: too_many_arguments)] pub const fn new (name : Name) -> Self { Self { name , } } } }
